-- Cau luyen dich tieng Anh (400 cau, 20 chu de). Doc qua API cong khai.
create table if not exists public.translate_sentences (
  topic_no    int  not null,
  topic_title text not null,
  idx         int  not null,
  vi          text not null,
  en          text not null,
  en_ipa      text not null default '',
  start_sec   numeric not null,
  vi_sec      numeric not null,
  en_sec      numeric not null,
  primary key (topic_no, idx)
);

alter table public.translate_sentences add column if not exists en_ipa text not null default '';
alter table public.translate_sentences enable row level security;

drop policy if exists "public read translate_sentences" on public.translate_sentences;
create policy "public read translate_sentences"
  on public.translate_sentences for select
  to anon, authenticated
  using (true);

on conflict (topic_no, idx) do update set
  topic_title = excluded.topic_title, vi = excluded.vi, en = excluded.en, en_ipa = excluded.en_ipa,
  start_sec = excluded.start_sec, vi_sec = excluded.vi_sec, en_sec = excluded.en_sec;
